<?php
declare(strict_types=1);
if (getenv('COUPONHUB_RUN_DB_TEST')!=='1') exit("SKIP: isolated database required.\n");
require __DIR__.'/../app/bootstrap.php';
if (config('database.database')!=='couponhub_merge_test' || (int)config('database.port')!==13379 || is_file(__DIR__.'/../config/local.php')) throw new RuntimeException('Unsafe test configuration');
ob_start(); session_save_path(sys_get_temp_dir());
use App\Core\{Database,Auth};
use App\Repositories\{UserRepository,CampaignRepository,AdminRepository,CouponRepository,AdminCouponRepository,MerchantRepository,InteractionRepository};
use App\Services\{CampaignService,CouponService,AdminCouponService,InteractionService};
function phaseCheck(bool $ok,string $label): void {if (!$ok) throw new RuntimeException('FAIL: '.$label); echo 'PASS: '.$label."\n";}
function phaseReject(callable $call,string $label): void {try {$call();} catch (RuntimeException $error) {phaseCheck(true,$label);return;} throw new LogicException('FAIL: accepted '.$label);}
$db=Database::connection();
phaseCheck((int)$db->query('SELECT @@port')->fetchColumn()===13379,'isolated database port');
$users=new UserRepository($db); $admin=$users->findByLogin('admin_demo'); $user=$users->findByLogin('user_demo'); $owner=$users->findByLogin('merchant_shops'); $other=$users->findByLogin('merchant_services');
$aid=(int)$admin['id']; $uid=(int)$user['id']; $oid=(int)$owner['id'];
$shop=(int)$db->query("SELECT id FROM merchants WHERE slug='demo-shopee'")->fetchColumn();
$grab=(int)$db->query("SELECT id FROM merchants WHERE slug='demo-grab'")->fetchColumn();
$shopping=(int)$db->query("SELECT id FROM categories WHERE slug='mua-sam'")->fetchColumn();
$food=(int)$db->query("SELECT id FROM categories WHERE slug='an-uong'")->fetchColumn();
phaseCheck($shop>0 && $grab>0 && $shopping>0 && $food>0,'real fixture identities');
$campaigns=new CampaignRepository($db); $service=new CampaignService($campaigns); $adminRepo=new AdminRepository($db); $coupons=new CouponRepository($db); $couponService=new CouponService($coupons);
$moderation=new AdminCouponService(new AdminCouponRepository($db),$couponService);
$input=['name'=>'Phase3 campaign','description'=>'Isolated verification','starts_at'=>date('Y-m-d\TH:i',time()-86400),'ends_at'=>date('Y-m-d\TH:i',time()+604800),'status'=>'PUBLISHED','banner_path'=>'assets/images/hero/category-food.webp'];
$platform=$service->create($aid,null,$input);
$merchant=$service->create($oid,$shop,array_replace($input,['name'=>'Phase3 merchant']));
phaseCheck($platform>0 && $merchant>$platform && $campaigns->findPublic($platform)['banner_path']===$input['banner_path'],'admin and merchant creation INSERT and persist banner');
phaseCheck(str_ends_with(campaignBannerUrl($campaigns->findPublic($platform)),'/assets/images/hero/category-food.webp'),'local banner resolves through app URL');
phaseReject(fn()=>$service->create($uid,null,$input),'USER cannot create admin campaign at write layer');
phaseReject(fn()=>$service->create((int)$other['id'],$shop,$input),'other merchant cannot create campaign for this shop');
foreach (['javascript:alert(1)','http://example.test/image.jpg','//example.test/image.jpg','../config/database.php','assets/images/../image.webp','public/images/missing.png','https://user:secret@example.test/image.jpg',str_repeat('a',501),['image']] as $bad) {
    phaseReject(fn()=>$service->create($aid,null,array_replace($input,['banner_path'=>$bad])),'unsafe or missing banner rejected');
}
$service->updateOwned($merchant,$oid,array_replace($input,['banner_path'=>'https://example.test/campaign.webp']));
phaseCheck($campaigns->findOwned($merchant,$oid)['banner_path']==='https://example.test/campaign.webp','edited remote HTTPS banner persists');
$service->updateOwned($merchant,$oid,array_replace($input,['banner_path'=>'']));
phaseCheck($campaigns->findOwned($merchant,$oid)['banner_path']===null && campaignBannerUrl($campaigns->findOwned($merchant,$oid))===null,'clearing banner restores default artwork');
phaseReject(fn()=>$service->updateOwned($merchant,(int)$other['id'],$input),'cross-merchant edit rejected');
phaseReject(fn()=>$service->create($aid,null,array_replace($input,['name'=>['bad']])),'array field rejected before SQL');
function phaseCoupon(Database $db,int $shop,int $category,string $suffix,string $channel,int $author): int {
    $db->prepare("INSERT INTO coupons(merchant_id,category_id,submitted_by,source,title,code,description,terms,discount_type,discount_value,min_order_amount,usage_channel,starts_at,ends_at,moderation_status,publication_status) VALUES(?,?,?,'OFFICIAL',?,?, 'Isolated test','Test only','FIXED_AMOUNT',20000,100000,?,UTC_TIMESTAMP()-INTERVAL 1 DAY,UTC_TIMESTAMP()+INTERVAL 10 DAY,'APPROVED','ENABLED')")
        ->execute([$shop,$category,$author,'Phase3 '.$suffix,'PHASE3_'.$suffix,$channel]);
    return (int)$db->lastInsertId();
}
$a=phaseCoupon($db,$shop,$shopping,'A','ONLINE',$aid); $b=phaseCoupon($db,$grab,$food,'B','BOTH',$aid); $c=phaseCoupon($db,$shop,$shopping,'C','BOTH',$aid);
$campaigns->attach($aid,$platform,$a); $campaigns->attach($aid,$platform,$b); $campaigns->attach($oid,$merchant,$c);
$campaigns->attach($oid,$merchant,$a);
phaseCheck((int)$db->query('SELECT COUNT(*) FROM coupons WHERE id='.$a)->fetchColumn()===1 && (int)$db->query('SELECT COUNT(*) FROM campaign_coupons WHERE coupon_id='.$a)->fetchColumn()===2,'one coupon can belong to multiple campaigns without cloning');
$campaigns->detachOwned($merchant,$a,$oid);
phaseCheck((int)$db->query('SELECT COUNT(*) FROM campaign_coupons WHERE coupon_id='.$a)->fetchColumn()===1,'detach removes only the selected campaign relation');
phaseReject(fn()=>$campaigns->attach($oid,$merchant,$b),'merchant campaign cannot attach another shop coupon');
phaseCheck($campaigns->publicFilteredListing('ALL',$shopping,'ALL',1,9,$grab)['total']===0,'combined filters require the same coupon, not separate coupons in one campaign');
$listed=$campaigns->publicFilteredListing('ALL',$food,'OFFLINE',999,9,$grab);
phaseCheck($listed['total']===1 && $listed['page']===1 && (int)$listed['items'][0]['coupon_count']===1 && (int)$listed['items'][0]['id']===$platform,'filtered count, BOTH channel and page bounds agree');
phaseCheck(array_column($campaigns->publicCoupons($platform,$food,'OFFLINE',$grab),'id')===[$b],'preview/detail use same merchant/category/channel filter');
phaseCheck($campaigns->publicCoupons($platform,$food,'BOTH',$grab)[0]['id']===$b,'exact BOTH filter is retained');
$adminRepo->setCampaignStatus($platform,'DRAFT',$aid);
phaseCheck($campaigns->findPublic($platform)===null && $campaigns->publicCoupons($platform)===[],'draft parent hides its coupons');
$adminRepo->setCampaignStatus($platform,'PUBLISHED',$aid);
phaseReject(fn()=>$adminRepo->setCampaignStatus($platform,'DISABLED',$uid),'USER cannot change campaign status in repository');
$interactions=new InteractionService(new InteractionRepository($db),$coupons);
$interactions->setFavorite($uid,$a,true); $interactions->setFavorite($uid,$a,true);
phaseCheck((int)$db->query("SELECT COUNT(*) FROM favorites WHERE user_id=$uid AND coupon_id=$a")->fetchColumn()===1,'favorite is idempotent');
$interactions->setVote($uid,$a,'WORKING'); $interactions->setVote($uid,$a,'NOT_WORKING');
phaseCheck((int)$db->query("SELECT COUNT(*) FROM votes WHERE user_id=$uid AND coupon_id=$a")->fetchColumn()===1,'vote updates one current record');
$report=$interactions->createReport($uid,$a,'FAKE','Please verify the source of this isolated coupon.');
phaseCheck($coupons->findPublic($a)!==null,'creating a report does not revoke a coupon');
$interactions->resolveReport($aid,$report,'DISMISSED','Verified source in the isolated test.');
$resolved=$db->query('SELECT * FROM reports WHERE id='.$report)->fetch();
phaseCheck($resolved['status']==='DISMISSED' && (int)$resolved['resolved_by']===$aid && $resolved['resolved_at']!==null && $resolved['resolution_note']!=='','report records status, actor, time and reason');
phaseReject(fn()=>$interactions->resolveReport($aid,$report,'RESOLVED','Cannot process the same report twice.'),'report cannot be processed twice');
$report2=$interactions->createReport($uid,$b,'OTHER','Please verify the conditions of this isolated offer.');
$interactions->resolveReport($aid,$report2,'RESOLVED','Conditions verified; coupon kept intact in isolated test.');
phaseCheck($db->query('SELECT status FROM reports WHERE id='.$report2)->fetchColumn()==='RESOLVED' && $coupons->findPublic($b)!==null,'RESOLVED records report outcome without deleting or disabling coupon');
$before=$db->query('SELECT * FROM coupons WHERE id='.$a)->fetch();
phaseReject(fn()=>$moderation->revoke($aid,$a,'short'),'revoke requires meaningful reason');
$moderation->revoke($aid,$a,'Withdrawn after verification in isolated test.');
$revoked=$db->query('SELECT * FROM coupons WHERE id='.$a)->fetch();
phaseCheck($revoked['publication_status']==='ARCHIVED' && $revoked['deleted_at']===null && $revoked['ends_at']===$before['ends_at'] && (int)$revoked['reviewed_by']===$aid && $revoked['reviewed_at']!==null,'revoke preserves dates/data and records admin provenance');
phaseCheck($coupons->findPublic($a)===null && $campaigns->publicCoupons($platform,0,'ALL',$shop)===[],'revoke immediately hides search/detail/campaign use');
phaseCheck((int)$db->query("SELECT COUNT(*) FROM activity_logs WHERE coupon_id=$a AND action='COUPON_REVOKE'")->fetchColumn()===1,'revoke audit log persists');
phaseReject(fn()=>$coupons->disableOwnedOfficial($oid,$a),'merchant cannot replace terminal revoke with DISABLED');
$edit=$before+['starts_at_utc'=>$before['starts_at'],'ends_at_utc'=>$before['ends_at']];
$toLocal=static fn(string $value): string => (new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('Y-m-d\TH:i');
$duplicateInput=array_replace($before,['code'=>'  PHASE3_DUPLICATE  ','starts_at'=>$toLocal($before['starts_at']),'ends_at'=>$toLocal($before['ends_at'])]);
$firstDuplicate=$couponService->submitOfficial($oid,$duplicateInput);
phaseReject(fn()=>$couponService->submitOfficial($oid,array_replace($duplicateInput,['code'=>'phase3_duplicate'])),'normalized same-shop overlapping code rejected');
$differentShop=$couponService->submitOfficial((int)$other['id'],array_replace($duplicateInput,['merchant_id'=>$grab]));
phaseCheck($differentShop!==$firstDuplicate,'same code remains valid for a different shop');
$storedEnd=$db->query('SELECT ends_at FROM coupons WHERE id='.$firstDuplicate)->fetchColumn();
$later=$couponService->submitOfficial($oid,array_replace($duplicateInput,['starts_at'=>$toLocal($storedEnd),'ends_at'=>$toLocal((new DateTimeImmutable($storedEnd,new DateTimeZone('UTC')))->modify('+1 day')->format('Y-m-d H:i:s'))]));
phaseCheck($later!==$firstDuplicate,'touching validity intervals do not falsely count as overlapping duplicates');
phaseReject(fn()=>$coupons->updateOwnedOfficial($oid,$a,$edit),'merchant cannot edit revoked coupon back to PENDING/ENABLED');
phaseReject(fn()=>$coupons->moderate($aid,$a,'APPROVED','ENABLED',null),'moderation cannot bypass revoke');
phaseReject(fn()=>$adminRepo->setMerchantStatus($shop,'LOCK',$uid,'This account has no administrative role.'),'USER cannot lock shop in repository');
phaseReject(fn()=>$adminRepo->setMerchantStatus($shop,'LOCK',$aid,''),'shop lock requires reason');
Auth::login($owner);
$adminRepo->setMerchantStatus($shop,'LOCK',$aid,'Fraud investigation in isolated environment.');
phaseCheck($coupons->findPublic($c)===null && $campaigns->findPublic($merchant)===null,'locked shop hides official coupon and owned campaign');
phaseReject(fn()=>$service->create($oid,$shop,$input),'old merchant session cannot create campaign for locked shop');
phaseReject(fn()=>$service->updateOwned($merchant,$oid,$input),'old merchant session cannot edit locked shop campaign');
phaseReject(fn()=>(new MerchantRepository($db))->updateProfile($shop,$oid,'Bad edit',null,null),'locked shop profile write rejected');
phaseReject(fn()=>$coupons->disableOwnedOfficial($oid,$c),'locked shop coupon write rejected');
$adminRepo->setMerchantStatus($shop,'UNLOCK',$aid,'Investigation complete in isolated environment.');
phaseCheck($coupons->findPublic($c)!==null && $coupons->findPublic($a)===null,'unlock restores eligible coupon but never revoked coupon');
phaseCheck((int)$db->query("SELECT COUNT(*) FROM activity_logs WHERE action IN ('MERCHANT_LOCK','MERCHANT_UNLOCK')")->fetchColumn()===2,'lock and unlock retain separate audit entries');
$db->prepare("UPDATE merchants SET status='PENDING' WHERE id=?")->execute([$shop]);
phaseCheck($coupons->findPublic($c)===null,'non-approved shop cannot expose official coupon');
$db->prepare("UPDATE merchants SET status='APPROVED' WHERE id=?")->execute([$shop]);
$db->prepare('UPDATE campaigns SET ends_at=UTC_TIMESTAMP()-INTERVAL 1 SECOND WHERE id=?')->execute([$platform]);
phaseCheck($campaigns->findPublic($platform)===null && $campaigns->findPublic($platform,true)!==null && $campaigns->publicCoupons($platform)===[],'ended campaign is readable explicitly but absent from active listings/offers');
phaseCheck($coupons->findPublic($b)!==null,'campaign expiry never changes coupon availability elsewhere');
Auth::logout();
echo "PASS: phase 3 integration acceptance. Reset disposable fixture before other suites.\n";
